def translator(mode):
    if mode not in ("en", "bilingual"):
        raise ValueError(
            "UI language must be en or bilingual (界面语言必须为 en 或 bilingual)."
        )
    return (
        (lambda value: ENGLISH.get(value, value))
        if mode == "en"
        else (lambda value: value)
    )


# Preserve readable separators for application status prefixes.
for _key in tuple(ENGLISH):
    if _key.startswith(
        (
            "Generating section ",
            "Saved section ",
            "Paused after error:",
            "Generation failed (",
            "Operation failed (",
        )
    ):
        ENGLISH[_key] = ENGLISH[_key].rstrip() + " "
